with parsed as (select id, customer_id, created_at, coupon_codes, ship_to, attributes, attributes['device'] as device, exists(items, x -> x.price > 100) as has_premium_item, ship_to.zip as ship_zip, size(attributes) as num_attributes from carts where array_contains(coupon_codes, 'SPRING10')) select case when num_attributes >= 72 then 'PREMIUM' else 'STANDARD' end as num_attributes_tier, min(created_at) as started_at, round(avg(num_attributes), 2) as avg_num_attributes from parsed group by case when num_attributes >= 72 then 'PREMIUM' else 'STANDARD' end order by avg_num_attributes;
